    async fn ensure_resource_name(db: &TestDb, calendar_id: i64, event_id: i64) -> String {
        let repo = CaldavRepository::new(db.pool.clone());
        let resource = repo
            .ensure_resource(calendar_id, event_id, 1000)
            .await
            .unwrap();
        resource.resource_name
