+<C:calendar-query xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/">
+  <D:prop>
+    <D:getetag/>
+    <D:getcontenttype/>
+    <C:calendar-data/>
+  </D:prop>
+  <C:filter>
+    <C:time-range start="{start}" end="{end}"/>
+  </C:filter>
+</C:calendar-query>"#
+        )
+    }
