    calendar_id: i64,
    event_id: i64,
    now: i64,
) -> Result<(), CaldavAuthError> {
    sqlx::query(
        "UPDATE caldav_event_resources
             SET event_id = ?, deleted_at = NULL, updated_at = ?
           WHERE calendar_id = ? AND event_id IS NULL AND deleted_at IS NOT NULL",
    )
    .bind(event_id)
    .bind(now)
    .bind(calendar_id)
    .execute(&self.pool)
    .await
    .map_err(|_| CaldavAuthError::Persistence)?;
    Ok(())
}

